@using sv_3f2af408b9314e1ba097a27f5c89d635.Services

<div class="change-password-panel">
    <button class="panel-toggle" @onclick="() => _expanded = !_expanded">
        @(_expanded ? "▼" : "▶") Change Password
    </button>

    @if (_expanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
            </div>
            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
            </div>
            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="toast-message error">@_error</div>
            }
            @if (_success)
            {
                <div class="toast-message success">Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePasswordAsync">Update Password</button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _error;
    private bool _success;

    private async Task UpdatePasswordAsync()
    {
        _error = null;
        _success = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "All fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _success = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }
}

